// This website represents a mutual fund distributor: only Regular Plan scheme
// entries from the displayed fund houses are shown. The runtime filter below is a
// second safeguard; the complete AMFI data is kept in ./amfi-snapshot-full.ts.
export const staticSchemes: readonly StaticSchemeRecord[] = rows
  .filter(
    ([amc, , , plan, option]) =>
      isPublicAmc(amc) && isPublicPlan(plan, option),
  )
  .map(([amc, name, category, plan, option]) => ({
    amc,
    name,
    category,
    plan,
    option,
  }));
